"@import "tailwindcss";

@layer base {
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    overflow-x: hidden;
    background-color: #070a13;
    color: #f3f4f6;
    font-family: 'Outfit', sans-serif;
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Custom scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #070a13;
  }
  ::-webkit-scrollbar-thumb {
    background: #111827;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #f59e0b;
  }
}

/* Centered Journey Ribbon Timeline Layout */
.journey-ribbon-container {
  position: relative;
  width: 100%;
  background-color: #070a13;
  overflow: hidden;
}

.ribbon-svg-backdrop {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 10;
}

.milestone-row {
  position: relative;
  width: 100%;
  box-sizing: border-box;
}

/* Desktop row heights and positioning with 3D perspective context */
@media (min-width: 1024px) {
  .milestone-row {
    height: 80vh;
    min-height: 580px;
    perspective: 1200px;
    transform-style: preserve-3d;
  }

  .milestone-year-capsule {
    position: absolute;
    top: 50%;
    transform: translate(-50%, -50%) scale(1);
    z-index: 30;
    transition: all 0.6s cubic-bezier(0.16, 1, 0.3, 1);
  }

  /* Even rows: capsule on left (35%), card on right */
  .milestone-row.even .milestone-year-capsule {
    left: 35%;
